"""Author the 30-topic expansion. This command never runs during a normal build.

Each of eight closed-task families has two numerical variants; four reasoning
families complete each 20-task packet. Independent checks live in the source
records and are evaluated by quality_assets, not by this authoring module.
"""
from pathlib import Path
from fractions import Fraction as F
import argparse
import json
import math

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'src' / 'quality-bank'
TASKS = []
PACKETS = []
CURRENT = None


def fmt(n):
    if isinstance(n, F):
        return str(n.numerator) if n.denominator == 1 else f'{n.numerator}/{n.denominator}'
    return str(n)


def packet(topic, skills, prerequisites, method):
    global CURRENT
    CURRENT = {'topicId': topic, 'skills': skills.split(), 'prerequisites': prerequisites.split(),
               'method': method, 'families': []}
    PACKETS.append(CURRENT)


def add(family, variant, prompt, answer, solution, hint, check, *, second='', skills=None, figure=None):
    category = 'single' if family <= 3 else 'combined' if family <= 6 else 'applied' if family <= 8 else 'reasoning'
    tid = CURRENT['topicId']
    qid = f'quality-{tid}-{family:02}-{variant}'
    q = {'id': qid, 'topicId': tid, 'family': f'quality:{tid}:{family:02}', 'canonicalId': qid,
         'category': category, 'kind': 'open' if family > 8 else 'number',
         'difficulty': 'Базовый' if family <= 3 else 'Средний' if family <= 5 or family == 7 else 'Повышенный',
         'prompt': prompt, 'answer': None if answer is None else float(answer) if isinstance(answer, F) else answer,
         'display': 'См. образец рассуждения' if answer is None else fmt(answer),
         'solution': solution, 'hint': hint, 'method': CURRENT['method'],
         'skills': list(skills or CURRENT['skills']), 'prerequisites': CURRENT['prerequisites'],
         'verification': check, 'revision': 1}
    if second:
        q['alternativeSolution'] = second
    if figure:
        q['figure'] = figure
    TASKS.append(q)
    if q['family'] not in CURRENT['families']:
        CURRENT['families'].append(q['family'])
    return q


def numeric(family, variant, prompt, answer, solution, hint, expression, **kw):
    return add(family, variant, prompt, answer, solution, hint,
               {'type': 'numeric', 'expression': expression}, **kw)


def reasoning(family, prompt, solution, hint, claims, rubric, form):
    q = add(family, 1, prompt, None, solution, hint, {'type': 'reasoning', 'claims': claims})
    q.update({'format': form, 'rubric': rubric})
    q['skills'] = list(dict.fromkeys(q['skills'] + [{'error': 'error-analysis', 'methods': 'method-comparison',
                         'counterexample': 'counterexample', 'insufficient': 'justification'}[form]]))


def coord_figure(points, segments=()):
    """Given points only, one scale for both axes, no answer geometry."""
    xs=[p[1] for p in points]+[0]; ys=[p[2] for p in points]+[0]
    lo,hi=min(xs)-1,max(xs)+1; bot,top=min(ys)-1,max(ys)+1
    scale=min(270/(hi-lo),150/(top-bot))
    xy=lambda x,y:(65+(x-lo)*scale,195-(y-bot)*scale)
    elements=[]
    def line(a,b):
        x1,y1=xy(*a);x2,y2=xy(*b);elements.append(dict(type='line',x1=x1,y1=y1,x2=x2,y2=y2))
    line((lo,0),(hi,0));line((0,bot),(0,top))
    for name,x,y in points:
        px,py=xy(x,y);elements.extend([dict(type='ellipse',x=px,y=py,rx=2.5,ry=2.5),dict(type='text',text=f'{name}({x}; {y})',x=px,y=py-12,size=12,anchor='middle')])
    byname={p[0]:p[1:] for p in points}
    for a,b in segments:line(byname[a],byname[b])
    return {'width':400,'height':240,'alt':'Данные точки на координатной плоскости: '+', '.join(f'{n}({x}; {y})' for n,x,y in points),
            'caption':'Одинаковый масштаб осей. Координаты заданы в условии.', 'elements':elements}


